pub fn encode(message: Vec<char>) -> Vec<char> {
    // Helper: given a vowel, map it according to the specified substitution
    fn map_vowel(c: char) -> char {
        match c {
            'a' => 'c',
            'e' => 'g',
            'i' => 'k',
            'o' => 'q',
            'u' => 'w',
            'A' => 'C',
            'E' => 'G',
            'I' => 'K',
            'O' => 'Q',
            'U' => 'W',
            _   => c, // should not happen for non-vowels
        }
    }

    let mut result = Vec::with_capacity(message.len());

    for ch in message {
        let out = match ch {
            ' ' => {
                // Spaces remain spaces
                ' '
            }
            // Vowels: first substitute, then swap case
            'a' | 'e' | 'i' | 'o' | 'u'
            | 'A' | 'E' | 'I' | 'O' | 'U' => {
                let mapped = map_vowel(ch);
                if mapped.is_ascii_lowercase() {
                    mapped.to_ascii_uppercase()
                } else {
                    mapped.to_ascii_lowercase()
                }
            }
            // Consonants: just swap case
            _ => {
                if ch.is_ascii_lowercase() {
                    ch.to_ascii_uppercase()
                } else {
                    ch.to_ascii_lowercase()
                }
            }
        };
        result.push(out);
    }

    result
}

